import sqlite3
from typing import Optional
from fastapi import FastAPI, HTTPException, status, Query
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, Field

def init_db(database_path: str):
    conn = sqlite3.connect(database_path)
    cursor = conn.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'todo'
        )
    """)
    conn.commit()
    conn.close()

class TaskCreate(BaseModel):
    title: str

class TaskUpdate(BaseModel):
    title: Optional[str] = None
    status: Optional[str] = None

def create_app(database_path: str = "tasks.db") -> FastAPI:
    init_db(database_path)
    app = FastAPI()

    @app.post("/tasks", status_code=status.HTTP_201_CREATED)
    def create_task(task: TaskCreate):
        if not isinstance(task.title, str) or not task.title.strip():
            raise HTTPException(status_code=422, detail="Title cannot be blank")
        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        cursor.execute("INSERT INTO tasks (title, status) VALUES (?, ?)", (task.title, "todo"))
        conn.commit()
        task_id = cursor.lastrowid
        cursor.execute("SELECT id, title, status FROM tasks WHERE id = ?", (task_id,))
        row = cursor.fetchone()
        conn.close()
        return {"id": row[0], "title": row[1], "status": row[2]}

    @app.get("/tasks")
    def list_tasks(
        q: Optional[str] = Query(None),
        status: Optional[str] = Query(None)
    ):
        conn = sqlite3.connect(database_path)
        conn.create_function("qldapm_casefold", 1, lambda s: s.casefold() if s is not None else "")
        cursor = conn.cursor()
        query = "SELECT id, title, status FROM tasks WHERE 1=1"
        params = []

        if q is not None:
            query += " AND qldapm_casefold(title) LIKE ? ESCAPE '\\'"
            escaped_q = q.casefold().replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
            params.append(f"%{escaped_q}%")

        if status is not None:
            if status not in ("todo", "in_progress", "done"):
                conn.close()
                raise HTTPException(status_code=422, detail="Invalid status")
            query += " AND status = ?"
            params.append(status)

        query += " ORDER BY id ASC"
        cursor.execute(query, params)
        rows = cursor.fetchall()
        conn.close()
        return [{"id": r[0], "title": r[1], "status": r[2]} for r in rows]

    @app.patch("/tasks/{task_id}")
    def update_task(task_id: int, task_update: TaskUpdate):
        if task_update.title is None and task_update.status is None:
            raise HTTPException(status_code=422, detail="Empty update")

        if task_update.title is not None:
            if not isinstance(task_update.title, str) or not task_update.title.strip():
                raise HTTPException(status_code=422, detail="Title cannot be blank")

        if task_update.status is not None:
            if task_update.status not in ("todo", "in_progress", "done"):
                raise HTTPException(status_code=422, detail="Invalid status")

        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        cursor.execute("SELECT id, title, status FROM tasks WHERE id = ?", (task_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            raise HTTPException(status_code=404, detail="Task not found")

        current_title, current_status = row[1], row[2]
        new_title = task_update.title if task_update.title is not None else current_title
        new_status = task_update.status if task_update.status is not None else current_status

        cursor.execute("UPDATE tasks SET title = ?, status = ? WHERE id = ?", (new_title, new_status, task_id))
        conn.commit()
        cursor.execute("SELECT id, title, status FROM tasks WHERE id = ?", (task_id,))
        updated_row = cursor.fetchone()
        conn.close()
        return {"id": updated_row[0], "title": updated_row[1], "status": updated_row[2]}

    @app.delete("/tasks/{task_id}", status_code=status.HTTP_204_NO_CONTENT)
    def delete_task(task_id: int):
        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        cursor.execute("SELECT id FROM tasks WHERE id = ?", (task_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            raise HTTPException(status_code=404, detail="Task not found")
        cursor.execute("DELETE FROM tasks WHERE id = ?", (task_id,))
        conn.commit()
        conn.close()
        return None

